from pqattest import (
    merkle_deployment_frontier,
    merkle_transport_deployment_frontier,
    merkle_transport_workload_frontier,
    merkle_mode_frontier,
    merkle_cardinality_frontier,
    merkle_verify_mode_frontier,
    profile,
)

def regret_ranking(frontier, metrics_n, weights_sets, tail):
    rows = [metrics_n(x) for x in frontier]
    d = len(rows[0])
    spans = [(min(r[i] for r in rows), max(r[i] for r in rows)) for i in range(d)]
    def norm(r):
        return tuple(Fraction(v-lo, hi-lo) if hi>lo else Fraction(0) for v,(lo,hi) in zip(r,spans))
    nrows = [norm(r) for r in rows]
    def scores(row, w):
        return sum((a*b for a,b in zip(row,w)), Fraction(0))/sum(w)
    srows = [[scores(r,w) for w in weights_sets] for r in nrows]
    best = [min(s[i] for s in srows) for i in range(len(weights_sets))]
    def key(i):
        reg = [srows[i][j]-best[j] for j in range(len(weights_sets))]
        return (max(reg), sum(reg,Fraction(0)), tuple(srows[i]), *tail(frontier[i]))
    return min(range(len(frontier)), key=key)

# 1) deployment: 4 dims: checkpoint, sig, proof, steps
f = merkle_deployment_frontier(16, (None, None, None, 9000))
print("deployment frontier size:", len(f))
def m_d(s):
    return (s.checkpoint_bytes, s.signature_wire_bytes, s.proof_wire_bytes,
            profile("merkle", w=s.w, height=s.height).steps)
tail_d = lambda s: (s.checkpoint_bytes, s.leaf_count, s.w, s.height)
found = None
for a in product(range(3), repeat=4):
    for b in product(range(3), repeat=4):
        if not any(a) or not any(b): continue
        i1 = regret_ranking(f, m_d, (a,), tail_d)
        i2 = regret_ranking(f, m_d, (a, b, b), tail_d)
        i3 = regret_ranking(f, m_d, (a, a, b), tail_d)
        if i1 != i2 or i1 != i3:
            found = (a, b, i1, i2, i3)
            break
    if found: break
print("deployment:", found and (found[0], found[1], f[found[2]].height, f[found[2]].w, f[found[3]].height, f[found[3]].w, f[found[4]].height, f[found[4]].w))
